  8	 * A behaviour key can only encode a solar-system rule if it says where a planet sits, how big it
  9	 * is or how hot it is. The source states none of those numbers and says the mechanics still need
 10	 * host confirmation, so a match here means unconfirmed host geography was inlined into the module.
 11	 */
 12	const SOLAR_SYSTEM_RULE_PATTERN = '/temperature|(solar|galaxy|orbit|planet|system)s?(position|slot|size|diameter)|(position|slot|size|diameter)s?(in|of|per|within)(solar|galaxy|orbit|planet|system)/';
 13	
 14	/** Bare segments that name solar-system geography on their own, whatever their parent is. */
 15	const SOLAR_SYSTEM_BARE_KEYS = ['galaxy', 'position', 'temperature'];
 16	
 17	/** Bare segments that are only geographic when a solar-system word appears somewhere in the path. */
 18	const SOLAR_SYSTEM_QUALIFIED_KEYS = ['system', 'size', 'slot'];
 19	
 20	const SOLAR_SYSTEM_LOCUS_PATTERN = '/solar|galaxy|orbit|planet|system/';
