 29	 * @return list<string>
 30	 */
 31	function solarSystemFilesUnder(string $directory, array $extensions): array
 32	{
 33	    if (! is_dir($directory)) {
 34	        return [];
 35	    }
 36	
 37	    $files = [];
 38	    $iterator = new RecursiveIteratorIterator(
 39	        new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS)
 40	    );
 41	
 42	    foreach ($iterator as $file) {
 43	        if (! in_array(strtolower($file->getExtension()), $extensions, true)) {
 44	            continue;
 45	        }
 46	
 47	        $files[] = $file->getPathname();
 48	    }
 49	
 50	    sort($files);
 51	
 52	    return $files;
 53	}
