 86	function solarSystemKeyIsForbidden(string $key): bool
 87	{
 88	    $normalised = solarSystemNormaliseKey($key);
 89	
 90	    if (preg_match(SOLAR_SYSTEM_RULE_PATTERN, $normalised) === 1) {
