173	function solarSystemArrayKeyPaths(array $data, string $prefix = ''): array
174	{
175	    $paths = [];
176	
177	    foreach ($data as $key => $value) {
178	        $path = $prefix === '' ? (string) $key : $prefix . '.' . $key;
179	        $paths[] = $path;
180	
181	        if (is_array($value)) {
182	            $paths = array_merge($paths, solarSystemArrayKeyPaths($value, $path));
183	        }
184	    }
185	
186	    return $paths;
187	}
