```php
<?php

namespace Modules\AI\Domain\Login;

use Modules\AI\Enums\GamePhase;
use OGame\Services\PlayerService;
use Symfony\Component\Yaml\Yaml;

/**
 * The account's game phase, derived from host state alone (architecture step 4, RV-011): one planet is
 * the opening, a colony means the account has settled, and the researched technology named in
 * `resources/behavior/phase.yaml` at its level means it has outgrown the mines. Managers and the
 * doctrine read this one answer instead of each restating a milestone.
 *
 * The class names no object: the technology and the two thresholds are data, so a modded universe moves
 * them without an edit.
 */
class GamePhaseMachine
{
    private const POLICY = '/resources/behavior/phase.yaml';

    /** @var array<string, mixed>|null */
    private static ?array $policy = null;

    public function of(PlayerService $player): GamePhase
    {
        if ($player->getResearchLevel($this->technology()) >= $this->int('late.level', 0)) {
            return GamePhase::Late;
        }

        if ($player->planets->planetCount() >= $this->int('mid.planets', 2)) {
            return GamePhase::Mid;
        }

        return GamePhase::Early;
    }

    /** The technology whose level marks the late phase, as the data names it. */
    private function technology(): string
    {
        return (string) ($this->policy()['late']['technology'] ?? '');
    }

    private function int(string $path, int $fallback): int
    {
        $value = $this->policy();
        foreach (explode('.', $path) as $segment) {
            $value = is_array($value) ? ($value[$segment] ?? null) : null;
        }

        return is_numeric($value) ? (int) $value : $fallback;
    }

    /** @return array<string, mixed> */
    private function policy(): array
    {
        if (self::$policy !== null) {
            return self::$policy;
        }

        $path = dirname(__DIR__, 3) . self::POLICY;
        $parsed = is_file($path) ? Yaml::parseFile($path) : [];

        return self::$policy = is_array($parsed) ? $parsed : [];
    }
}
```
