34	        if ($report->ships === null || $report->defense === null) {
35	            return null;
36	        }
37	
38	        $live = Planet::query()
39	            ->where('galaxy', (int) $report->planet_galaxy)
40	            ->where('system', (int) $report->planet_system)
41	            ->where('planet', (int) $report->planet_position)
42	            ->where('planet_type', (int) $report->planet_type)
43	            ->where('destroyed', 0)
44	            ->first();
45	        if ($live === null) {
46	            return null;
47	        }
48	
49	        $seen = $live->replicate();
50	        $seen->id = $live->id;
51	        $seen->exists = false;
52	
53	        foreach ([...ObjectService::getShipObjects(), ...ObjectService::getDefenseObjects()] as $object) {
54	            $seen->{$object->machine_name} = (int) ($report->ships[$object->machine_name] ?? $report->defense[$object->machine_name] ?? 0);
55	        }
56	
57	        $resources = $report->resources ?? [];
58	        $seen->metal = (float) ($resources['metal'] ?? 0);
59	        $seen->crystal = (float) ($resources['crystal'] ?? 0);
60	        $seen->deuterium = (float) ($resources['deuterium'] ?? 0);
61	
62	        return $this->planetServiceFactory->makeFromModel($seen);
63	    }
